  svg.appendChild(el("text",{x:bocX-4,y:margin.top+12,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "BDC INCHANGÉ 15/07"));

