  svg.appendChild(el("text",{x:jobsX-4,y:margin.top+PH-6,"text-anchor":"end","font-size":"7","font-weight":"700","fill":"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "EMPLOI US"));

